    "id": "second_summit",
    "name": "The Second Diplomatic Summit",
    "title": "The Trainwreck That Actually Worked",
    "date": "Mid-1040 BF — exact date disputed because nobody wants to claim ownership of the calendar entry",
    "era": "Modern Crisis — Post-Planar Fracture diplomatic scramble",
    "location": "Sarasaland Royal Palace — Princess Daisy hosting, and thank the STARS for that",
    "type": "Diplomatic Summit / Humanitarian Achievement / Public Relations Catastrophe",
    "status": "Concluded — relief program operational, everything else on fire",
    "image": "",
    "imageCaption": "Official summit photographs exist but nobody looks happy in them.",
